      };

      const req = http.request(options, (res) => {
        let data = '';
        res.on('data', (chunk) => { data += chunk; });
        res.on('end', () => {
          serverProcess.kill(); // Clean up the child process after testing

          console.log('=== Path Traversal PoC Response ===');
