   if (!app.dispatch || typeof app.dispatch.static !== 'function') {
     throw new TypeError('Vulnerable dispatch.static handler not found on app object.');
   }

   // 3. Configure the base static directory path.
   // Changing this to a deep subdirectory allows '../../' traversal to reach root directories.
   app.static_route = '/var/www/public/';
   if (app.dispatch) {
     app.dispatch.static_route = app.static_route;
   }

