   // In unpatched versions, this path is directly passed to fs.exists without validation.
   let interceptedPath = null;
   const originalFSExists = fs.exists.bind(fs);

   // Monkey-patch fs.exists synchronously to capture the constructed full_path during runtime
   fs.exists = function(full_path, callback) {
     interceptedPath = full_path;
     console.log(`[PoC] Interception successful: Attempted full_path is '${full_path}'`);

