   const dirty = require('dirty-json');

   // The vulnerable regex in getLexer is: /\"((?:[^\"\\\\]+|\\\\.)*)(\"|$)/
   // We deliberately construct a string literal that starts with '"' but lacks the closing '"'.
   // By repeating an alternating pattern ('a\b'), we create exponential ambiguity for the 
   // regex engine when it fails to find the terminating quote.

   let maliciousPayload = '"';
